import React, { Component } from 'react';
import { Card, Row, Col ,Popover,Icon,Avatar} from 'antd';   
// import {profileGet} from '../../services/Api'; 
// import {TotalTransactions,AmountTransacted} from '../../calculations/TransactionCalculation';
import './Style.scss';

const { Meta } = Card;
class Dashboard extends Component { 
    constructor(props){
    super(props)
    this.state={
        short:'',
        mounted:false,
        username:'',
        transactions:'',
        amounttransacted:'',
        wallets:[],
    }
}

  componentWillUnmount() {
    clearInterval(this.intervalID);
  }

  async componentDidMount() {
    // const Profile= await profileGet();
    // const Transactions= await TotalTransactions();
    // console.log("TRANS",Transactions)
    // const amountTransacted=await AmountTransacted();
    // console.log("Amount",amountTransacted);

    // this.setState({
    //     username:Profile.data.fullName,
    // });
  }

    render() {
        return (
    <div>
        <Row gutter={15}  justify="space-between" align="middle">
                <Col span={12}  style={{paddingTop:10,paddingRight:5}} md={{span:12}} lg={{span:8}}>
                    <Card >
                <Row>
                    <Col lg={12} md={6}>
                    <h6 style={{color:"#2d1582"}}>Amount Transacted</h6>
                    </Col>
                    <Col lg={12} md={6}>
                          <div style={{float: 'right'}}>
                            <Icon type="dollar"  style={{ fontSize: '32px', color: '#08c', align:'left' }} />
                            </div>
                     </Col>
                    {/* <p>{this.state.amounttransacted} ETH</p> */}
                    </Row> 
                    </Card>

                </Col>
                <Col span={12} style={{paddingTop:10,paddingRight:5}} md={{span:12}} lg={{span:8} }>

                <Card >
                <Row>
                    <Col lg={12} md={6}>
                    <h6 style={{color:"#2d1582"}}>Number of Transations</h6>
                    </Col>
                    <Col lg={12} md={6}>
                          <div style={{float: 'right'}}>
                            <Icon type="star" theme="filled" style={{ fontSize: '16px', color: '#08c', align:'left' }} />
                            </div>
                     </Col>
                    {/* <p>{this.state.amounttransacted} ETH</p> */}
                    </Row> 
                    </Card>

                </Col>
                <Col   style={{paddingTop:10,paddingRight:5}} span={12} md={{span:12}} lg={{span:8}}>		
                <Card >
                <Row>
                    <Col lg={12} md={6}>
                    <h6 style={{color:"#2d1582"}}>Number of Orders</h6>
                    </Col>
                    <Col lg={12} md={6}>
                          <div style={{float: 'right'}}>
                            <Icon type="star" theme="filled" style={{ fontSize: '16px', color: '#08c', align:'left' }} />
                            </div>
                     </Col>
                    {/* <p>{this.state.amounttransacted} ETH</p> */}
                    </Row> 
                    </Card>
            </Col>
        </Row>

    </div>
        );
    }
}
export default (Dashboard);
